#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // Require exactly two arguments: shift and text
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    // Parse shift argument, ensure it is a valid integer with no extra characters
    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }

    // Normalize shift to the range [0,25]
    int s = (int)shift % 26;
    if (s < 0) s += 26;

    const char *text = argv[2];
    size_t len = strlen(text);
    // The original binary limits the input length to 1024 characters
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (char)('A' + (c - 'A' + s) % 26);
        } else if (c >= 'a' && c <= 'z') {
            c = (char)('a' + (c - 'a' + s) % 26);
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
